SELECT count(DISTINCT m.id)
FROM membership m JOIN membership_role mr ON mr.membership_id = m.id JOIN role r ON r.id = mr.role_id
LEFT JOIN role_permission rp ON rp.role_id = r.id
LEFT JOIN permission p ON p.id = rp.permission_id AND p.status = 'active' AND NOT p.deleted
WHERE m.tenant_id = #{tenantId} AND m.status = 'active' AND NOT m.deleted AND NOT r.deleted
AND (r.code IN
#{code}
OR p.code IN
#{code}
)
